R.append((7739965,
("Ensalada de pollo bang bang", "Un platillo rápido y sencillo de pollo jugoso y ensalada con un toque cítrico.", "2", "498 g",
 ["2 filetes de pechuga de pollo (200 g)", "1 cucharadita de aceite de canola", "1 cebolla, finamente picada", "1 chile rojo, finamente picado", "3 dientes de ajo, machacados", "4 cm de jengibre, finamente picado", "2 cucharadas de agua", "2 cucharaditas de crema de cacahuate", "2 cucharaditas de miel", "2 cucharaditas de aceite de sésamo", "4 cebollines, en tiras finas tipo palillo", "2 zanahorias, en cintas hechas con un pelador de verduras", "100 g de pepino, en palitos pequeños", "100 g de hojas de lechuga, rasgadas en trozos pequeños", "2 cucharaditas de salsa de soya reducida en sal", "ralladura y jugo de 1 limón, más gajos para servir", "25 g de cilantro fresco"],
 ["Ponga el pollo en una cacerola pequeña con agua hirviendo. Deje que vuelva a hervir, baje el fuego y cocine a fuego lento durante 10 minutos, hasta que esté bien cocido por dentro. Retire del fuego y déjelo en el agua 5 minutos.", "Para la ensalada, corte los cebollines en trozos de 3 cm y luego córtelos a lo largo para obtener tiras finas. Prepare todos los demás ingredientes de la ensalada, mézclelos y resérvelos.", "Ponga el aceite en una cacerola pequeña, agregue la cebolla y cocine de 3 a 4 minutos. Luego agregue el chile, el ajo y el jengibre, y revuelva durante 1 minuto. Agregue el agua, la miel, la crema de cacahuate y el aceite de sésamo, y revuelva hasta que todo se disuelva.", "Corte el pollo en trozos pequeños y delgados, agréguelos a la salsa y mezcle para cubrirlos bien.", "Ponga la ensalada en un plato y acomode el pollo alrededor. Sirva con gajos de limón."],
 ["Este platillo queda igual de bien con camarones cocidos o cerdo en lugar de pollo.", "Para una opción vegetariana, pruebe con tofu marinado.", "Para que esta ensalada no tenga gluten, solo tiene que usar tamari sin gluten en lugar de la salsa de soya.", "@FV"], []),
("سلطة دجاج بانغ بانغ", "طبق سريع وبسيط من الدجاج الطري والسلطة المنعشة.", "2", "498 جم",
 ["2 شريحة صدر دجاج (200 جم)", "1 ملعقة صغيرة زيت اللفت (كانولا)", "1 حبة بصل، مفرومة ناعمًا", "1 حبة فلفل أحمر حار، مفرومة ناعمًا", "3 فصوص ثوم، مهروسة", "4 سم زنجبيل، مفروم ناعمًا", "2 ملعقة كبيرة ماء", "2 ملعقة صغيرة زبدة الفول السوداني", "2 ملعقة صغيرة عسل", "2 ملعقة صغيرة زيت سمسم", "4 حبات بصل أخضر، مقطعة إلى أعواد رفيعة", "2 حبة جزر، مقشرة إلى شرائح طويلة بمقشرة الخضار", "100 جم خيار، مقطع إلى أعواد صغيرة", "100 جم أوراق خس، ممزقة إلى قطع صغيرة", "2 ملعقة صغيرة صلصة صويا مخفضة الملح", "قشر وعصير ليمونة خضراء واحدة، إضافة إلى أرباع للتقديم", "25 جم كزبرة خضراء طازجة"],
 ["ضع الدجاج في قدر صغير من الماء المغلي. اتركه حتى يعود إلى الغليان، ثم خفّف النار واتركه على نار هادئة لمدة 10 دقائق حتى ينضج تمامًا. أبعده عن النار واتركه في الماء لمدة 5 دقائق.", "للسلطة، قطّع البصل الأخضر إلى قطع بطول 3 سم ثم اشقّها طوليًا للحصول على أعواد رفيعة. جهّز باقي مكونات السلطة، واخلطها معًا وضعها جانبًا.", "ضع الزيت في قدر صغير، ثم أضف البصل واطهه لمدة 3–4 دقائق. بعد ذلك أضف الفلفل الحار والثوم والزنجبيل وقلّب لمدة دقيقة واحدة. أضف الماء والعسل وزبدة الفول السوداني وزيت السمسم، وقلّب حتى يذوب كل شيء.", "قطّع الدجاج إلى قطع صغيرة رقيقة وأضفه إلى الصلصة، مع التقليب لتغليفه جيدًا.", "ضع السلطة في طبق ورتّب الدجاج حولها من الخارج. قدّمها مع أرباع الليمون الأخضر."],
 ["يناسب هذا الطبق الروبيان المطبوخ أو لحم الخنزير بالقدر نفسه بدلًا من الدجاج.", "للحصول على خيار نباتي، جرّب استخدام التوفو المتبّل.", "لجعل هذه السلطة خالية من الغلوتين، كل ما عليك فعله هو استخدام صلصة التاماري الخالية من الغلوتين بدلًا من صلصة الصويا.", "@FV"], [])))
